import{_ as a,H as e,f as r,i as t}from"./chunks/framework.Cvt1eIE0.js";const _=JSON.parse('{"title":"第十章 新しい家族","description":"","frontmatter":{},"headers":[],"relativePath":"story/5-3.md","filePath":"story/5-3.md"}'),o={name:"story/5-3.md"};function h(l,p,s,i,n,d){return e(),r("div",null,[...p[0]||(p[0]=[t('<h1 id="第十章-新しい家族" tabindex="-1">第十章 新しい家族 <a class="header-anchor" href="#第十章-新しい家族" aria-label="Permalink to &quot;第十章 新しい家族&quot;">​</a></h1><p>王国歴十九年。</p><p>PIGLIN KINGDOMは、かつてないほどの平和を迎えていた。</p><p>市場には笑顔があふれ、子供たちは走り回り、王都 GOLDEN BASTIONには、毎日楽しそうな声が響いていた。</p><p>そして。</p><p>王宮では。</p><p>「陛下！」</p><p>「王妃様！」</p><p>「おめでとうございます！」</p><p>歓声と拍手。</p><p>「男の子ですよ！」</p><p>「元気な王子様です！」</p><p>オーレックスは目を丸くした。</p><p>「……。」</p><p>「本当に？」</p><p>「はい。」</p><p>「とっても元気です！」</p><p>「リリア！」</p><p>王妃のもとへ駆け寄る黄金王。</p><p>リリアは少し疲れていたが、優しく微笑んでいた。額には、まだ汗が滲んでいた。それでも、その表情には、戦のあとの兵士の顔とはまったく違う、満ち足りた静けさがあった。</p><p>「オーレックスさん。」</p><p>「見てください。」</p><p>「……。」</p><p>小さな命。</p><p>小さな手。</p><p>その手は、まだ何も知らない。剣を握ったこともなく、冠の重さも知らない。ただ、柔らかく、確かに、そこに在った。</p><p>「かわいい。」</p><p>オーレックスの目から、自然と涙がこぼれた。鍛冶屋の手の記憶が、不意に胸の中で重なった。あの大きく硬い、しかし優しかった父の手。今、自分の腕の中にあるのは、まだあんなに小さな手だった。いつか、この手も、誰かを守るために伸びていくのだろうか。</p><p>「ありがとう。」</p><p>「リリア。」</p><p>「ありがとう。」</p><p>「ふふ。」</p><p>「パパになりましたね。」</p><p>こうして。</p><p>第一王子。</p><p>Aurel Goldtusk。</p><p>アウレル・ゴールドタスクが誕生した。</p><hr><h1 id="第十一章-大騒ぎの王宮" tabindex="-1">第十一章 大騒ぎの王宮 <a class="header-anchor" href="#第十一章-大騒ぎの王宮" aria-label="Permalink to &quot;第十一章 大騒ぎの王宮&quot;">​</a></h1><p>数年後。</p><p>「スターリンおじちゃーん！」</p><p>「おう！」</p><p>「今日は何して遊ぶ！」</p><p>「剣術！」</p><p>「駄目です。」</p><p>ピックバーグが即座に止めた。</p><p>「遊びです。」</p><p>「えー。」</p><p>「つまんない！」</p><p>「駄目。」</p><p>「子供用の木の剣。」</p><p>「それならよし！」</p><p>「やったー！」</p><p>スターリンは完全に遊び相手になっていた。あの大斧で何万もの兵を打ち倒した将軍が、今は木の剣を片手に、満面の笑みで庭園を駆け回っている。誰がその姿を見ても、戦記の英雄だとは信じないだろう。</p><p>「行くぞ！」</p><p>「うおおお！」</p><p>「待て待てー！」</p><p>庭園中を走り回る二人。</p><p>「君は子供なの？」</p><p>ピックバーグは呆れていた。</p><p>「心は少年だからな！」</p><p>「威張ることじゃない。」</p><hr><p>そして。</p><p>「おぎゃあ！」</p><p>「おぎゃあ！」</p><p>「また泣いてる！」</p><p>数年前に生まれた第二王女。</p><p>Flora Goldtusk。</p><p>フローラ・ゴールドタスク。</p><p>その泣き声は、玉座の間まで響くほど、力強かった。</p><p>「大変！」</p><p>「ミルク！」</p><p>「毛布！」</p><p>王宮中が大騒ぎ。侍女たちが走り回り、扉が次々と開閉する音が、まるで小さな攻防戦のように響いた。</p><p>「はっはっは！」</p><p>「戦争より忙しいな！」</p><p>スターリンは大笑いした。</p><p>「本当だね。」</p><p>オーレックスも笑う。</p><p>リリアも笑う。</p><p>ピックバーグも、珍しく優しく微笑んでいた。記録ばかりを好んだ研究者の顔が、今は、ただの「おじさん」の顔になっていた。</p><p>平和。</p><p>それは、こういうものなのかもしれない。</p><p>数万の兵が雷鳴のように轟いた戦場の記憶と、赤ん坊の泣き声で揺れる王宮。そのどちらも、同じ一人の男が見てきた光景だった。だからこそ、今この瞬間の騒がしさが、何よりも尊く思えた。</p><hr><h1 id="第十二章-黄金時代" tabindex="-1">第十二章 黄金時代 <a class="header-anchor" href="#第十二章-黄金時代" aria-label="Permalink to &quot;第十二章 黄金時代&quot;">​</a></h1><p>王国歴二十五年。</p><p>PIGLIN KINGDOMは、最大の繁栄を迎えていた。</p><p>王立大学。</p><p>王立博物館。</p><p>巨大鉄道網。</p><p>海軍基地。</p><p>新しい町。</p><p>人々の笑顔。</p><p>蒸気を上げて走る鉄道の音が、玄武岩デルタの果てまで響いていた。博物館には、忘れられた砦から発見された古代の品々が、丁寧に並べられていた。大学の講堂では、若い学者たちが、ピックバーグの著した古文書の解読書を読みながら、夜遅くまで議論を続けていた。</p><p>歴史家たちは、後にこの時代をこう呼ぶ。</p><p>「黄金時代」</p><p>と。</p><p>そして。</p><p>人々は、こう語り継いだ。</p><p>「KING PIGLIN Iの時代は幸せだった。」</p><p>「誰もが笑っていた。」</p><p>「優しい王様だった。」</p><p>「素晴らしい時代だった。」</p><p>噴水広場には、今も子供たちが集まり、本を片手に座り込んでいる姿が見られた。その光景は、誰に教えられたわけでもなく、ただ自然に、王都の風景の一部になっていた。</p><hr><h1 id="第十三章-星空の下で" tabindex="-1">第十三章 星空の下で <a class="header-anchor" href="#第十三章-星空の下で" aria-label="Permalink to &quot;第十三章 星空の下で&quot;">​</a></h1><p>夜。</p><p>王宮の庭園。</p><p>久しぶりに、三人が集まっていた。</p><p>スターリン。</p><p>ピックバーグ。</p><p>そして。</p><p>Aurex Goldtusk。</p><p>紫色がかった星々が、ネザーの天井の隙間から、わずかに覗いていた。それは、エンドの空に似ているようで、どこか違う、静かな光だった。</p><p>「平和だなぁ。」</p><p>スターリンは寝転がる。草の感触が、昔と変わらず、少し痒かった。</p><p>「平和だね。」</p><p>ピックバーグも空を見上げる。</p><p>「ここまで来るとは思わなかった。」</p><p>オーレックスは笑った。</p><p>「旅してた頃は。」</p><p>「まさか王様になるなんて。」</p><p>「俺も。」</p><p>「まさか英雄になるとは思わなかった。」</p><p>「僕も。」</p><p>「まさか友達ができるとは思わなかった。」</p><p>三人は笑った。あの真紅の森が燃えた夜から、ずいぶん長い旅をしてきた。村を救い、橋を架け、冠を見つけ、戦争を終わらせ、そして今、ただ星を見上げて笑い合っている。</p><p>昔と変わらない。</p><p>何一つ変わらない。</p><p>ただ。</p><p>みんな少し年を取った。</p><p>それだけだった。</p><hr><h1 id="終章" tabindex="-1">終章 <a class="header-anchor" href="#終章" aria-label="Permalink to &quot;終章&quot;">​</a></h1><p>翌朝。</p><p>「パパ！」</p><p>「見て見て！」</p><p>アウレルが駆け寄ってくる。木の剣を、誇らしげに掲げていた。</p><p>「どうした？」</p><p>「剣の練習！」</p><p>「スターリンおじちゃんに教わった！」</p><p>「こら！」</p><p>「危ないこと教えない！」</p><p>リリアは笑う。</p><p>「はっはっは！」</p><p>スターリンは逃げる。</p><p>「待ちなさい！」</p><p>「助けてくれ！」</p><p>「知らないよ。」</p><p>ピックバーグは本を読んでいる。視線だけを、ちらりとそちらへ向けて、また紙面に戻した。</p><p>そして。</p><p>オーレックスは、そんなみんなを見て、静かに微笑んだ。</p><p>朝の光が、庭園のグロウベリーを淡く照らしていた。あの日、小さな女の子から花を一輪受け取った場所も、リリアにプロポーズをした場所も、今はこうして、笑い声に包まれている。</p><p>「幸せだな。」</p><p>それ以上の言葉は、必要なかった。</p><p>英雄。</p><p>王。</p><p>伝説。</p><p>そんな肩書きよりも。</p><p>家族。</p><p>仲間。</p><p>笑顔。</p><p>それこそが、彼が守りたかったものだった。</p><hr><p>しかし。</p><p>時は止まらない。</p><p>子供たちは成長し。</p><p>英雄たちは老いていく。</p><p>いつか。</p><p>別れの日は訪れる。</p><p>それでも。</p><p>共に笑い。</p><p>共に泣き。</p><p>共に歩んだ日々は、決して消えない。</p><p>その物語は。</p><p>もうすぐ、静かに幕を下ろそうとしていた。</p><hr><p>PIGLIN KING</p><p>第五巻 王家の物語</p><p>完</p>',182)])])}const u=a(o,[["render",h]]);export{_ as __pageData,u as default};
